with q as (select * from (values
('pcac-lc129-art101-first-group-25','LC nº 129/2004 — primeiro grupo','Permutar horário de serviço sem autorização expressa da autoridade policial hierarquicamente superior configura transgressão:','(A) do primeiro grupo.\n(B) do segundo grupo.\n(C) do terceiro grupo.\n(D) do quarto grupo.\n(E) não disciplinar.','A','O art. 101, I, classifica essa conduta no primeiro grupo.'),
('pcac-lc129-art103-absence-26','LC nº 129/2004 — terceiro grupo','A ausência injustificada do policial civil por até 30 dias consecutivos é classificada, em regra, como transgressão:','(A) do primeiro grupo.\n(B) do segundo grupo.\n(C) do terceiro grupo.\n(D) do quarto grupo.\n(E) não prevista.','C','O art. 103, I, prevê ausência injustificada de até 30 dias consecutivos no terceiro grupo.'),
('pcac-lc129-art104-absence-27','LC nº 129/2004 — quarto grupo','O abandono do cargo ou ausência injustificada por mais de 30 dias consecutivos integra:','(A) o primeiro grupo.\n(B) o segundo grupo.\n(C) o terceiro grupo.\n(D) o quarto grupo.\n(E) apenas infração penal sem reflexo disciplinar.','D','O art. 104, VI, classifica a ausência superior a 30 dias consecutivos, sem justificativa, no quarto grupo.'),
('pcac-lc129-art103-art104-secrecy-28','LC nº 129/2004 — sigilo','A revelação culposa de informação sigilosa, com prejuízo ao Estado ou a particular, é prevista no terceiro grupo; a revelação dolosa de segredo funcional com prejuízo, no quarto grupo. Essa afirmação é:','(A) falsa: ambas estão no segundo grupo.\n(B) verdadeira, conforme arts. 103, XIII, e 104, III.\n(C) falsa: ambas geram advertência.\n(D) verdadeira apenas se ocorrer durante o expediente.\n(E) falsa: a lei não diferencia dolo e culpa.','B','A lei distingue expressamente a revelação culposa (art. 103, XIII) da dolosa (art. 104, III), ambas com exigência de prejuízo.'),
('pcac-lc129-art127-syndicance-29','LC nº 129/2004 — sindicância','Após a alteração da LC nº 293/2014, a sindicância deve ser concluída em 30 dias:','(A) prorrogáveis sempre por mais 30 dias, como limite fixo.\n(B) improrrogáveis.\n(C) prorrogáveis mediante solicitação fundamentada, sem que o art. 127 fixe expressamente teto de mais 30 dias.\n(D) prorrogáveis por decisão informal.\n(E) em 60 dias, sem possibilidade de prorrogação.','C','A redação atual do art. 127 retirou a expressão “por mais trinta dias”; exige solicitação fundamentada, sem repetir esse limite numérico.'),
('pcac-lc129-art128-syndicance-30','LC nº 129/2004 — defesa na sindicância','Concluída a produção de provas na sindicância, o sindicado tem prazo para defesa escrita de:','(A) 48 horas.\n(B) 5 dias.\n(C) 10 dias.\n(D) 15 dias.\n(E) 30 dias.','C','O art. 128, § 1º, prevê dez dias para defesa escrita após a conclusão da produção de provas.'),
('pcac-lc129-art133-pad-31','LC nº 129/2004 — prazo do PAD','O prazo de conclusão do processo administrativo disciplinar é de:','(A) 30 dias improrrogáveis.\n(B) 30 dias prorrogáveis por 30.\n(C) 60 dias, prorrogáveis por igual prazo.\n(D) 90 dias, sem prorrogação.\n(E) 120 dias, prorrogáveis por 60.','C','O art. 133, na redação da LC nº 208/2010, estabelece 60 dias, prorrogáveis por igual prazo, contados da publicação.'),
('pcac-lc129-art138-witnesses-32','LC nº 129/2004 — prova testemunhal no PAD','Quantas testemunhas o acusado pode arrolar no PAD, conforme o art. 138, § 1º?','(A) Até 3.\n(B) Até 5.\n(C) Até 6.\n(D) Até 8.\n(E) Até 10.','D','O art. 138, § 1º, permite ao acusado arrolar até oito testemunhas.'),
('pcac-lc129-art148a-appeal-33','LC nº 129/2004 — recurso no PAD','O recurso do acusado contra o relatório do PAD, previsto no art. 148-A, § 3º, deve ser interposto no prazo de:','(A) 5 dias.\n(B) 10 dias.\n(C) 15 dias.\n(D) 20 dias.\n(E) 30 dias.','B','O art. 148-A, § 3º, prevê dez dias para o recurso dirigido ao Delegado-Geral, que o submete ao Conselho Superior.'),
('pcac-lc129-art149-deliberation-34','LC nº 129/2004 — Conselho Superior','Após diligências determinadas pelo Conselho Superior no recurso de PAD, o acusado tem prazo para se manifestar sobre as provas de:','(A) 2 dias.\n(B) 5 dias.\n(C) 10 dias.\n(D) 15 dias.\n(E) 20 dias.','B','O art. 149, § 3º, prevê cinco dias para manifestação do acusado sobre as provas resultantes da diligência.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
